def lower_words(text):
    """
    Splits text into words, lowercases each word, and counts them.

    Parameters:
        text (str): Input text to process.

    Returns:
        tuple: A tuple containing the list of lowercase words and a count of those words.
               If the input is empty or None, returns an empty tuple with a count of 0.
    """
    if not isinstance(text, str):
        return (None, 0)

    words = text.split()
    result = []
    count = 0

    for word in words:
        if word:
            result.append(word.lower())
            count += 1

    return (result, count)
